mapper.insert:
INSERT INTO shipping_address (
    address_id, member_id, address_name, recipient_name, phone, 
    zip_code, base_address, detail_address, is_default, request_msg
) VALUES (
    seq_shipping_address.NEXTVAL, #{member_id}, #{address_name}, #{recipient_name}, #{phone}, 
    #{zip_code}, #{base_address}, #{detail_address}, #{is_default}, #{request_msg}
)

mapper.update:
UPDATE shipping_address 
SET is_default = 'Y' 
WHERE address_id = #{addressId} 
  AND member_id = #{memberId}

mapper.delete:
DELETE FROM shipping_address 
WHERE address_id = #{addressId} 
  AND member_id = #{memberId}
